import sys

PATH = 'generate_manuscript_nc.py'
src = open(PATH, encoding='utf-8').read().splitlines()

REPL = [
    (r"""p('CKI reframes transcriptomic comparison""",
     r"""p('CKI reframes transcriptomic comparison\u2014from measuring absolute distance to quantifying functional divergence relative to an internal baseline\u2014but is better described as a recombination of established ideas than a conceptual shift: reference genes have long anchored normalization and quality control [29], the constrained-variance property of housekeeping genes is characterized genomically [13,30], and gene-specific noise floors are central to the transcriptional-noise literature [31-33]. CKI\u2019s contribution is to combine these ingredients into a per-comparison, design-testable index with explicit split-half calibration and a design-matched permutation null. The key assumption is that housekeeping (HK) genes are under stabilizing selection constraining their expression variance; unlike Ka/Ks\u2014where a shared mutation rate cancels mathematically\u2014CKI uses empirically defined HK genes as baseline, lacking comparable mechanistic cancellation, so CKI is a heuristic index rather than a formal measure of selection. The empirical calibration (mean \u03c9 = 7.70, 95% CI [7.37, 8.02]) indicates k_f systematically exceeds k_n even for identical populations; we therefore use \u03c9_cal = \u03c9 / 7.70 as the operational scale, interpreted relative to the empirical equivalent-population distribution rather than fixed cut-offs.')"""),
    (r"""p('CKI is a divergence index""",
     r"""p('CKI is a divergence index, not a classifier\u2014by design. Classifying cell types from transcriptomic data is largely solved; CKI answers a complementary question: regardless of labels, how much functional divergence separates two populations relative to their shared baseline? The negative correlation with standard metrics initially suggested complementary information, but decomposition showed it to be partly a denominator effect, so \u03c9 is a composite of numerator and denominator information rather than an independent dimension. The ratio earns its increment over k_f under controlled ground truth (AUC 0.80 versus 0.72 in marrow; 0.91 versus 0.86 in skin) and in drift rejection; on real-data orderings the increment is not established, and k_f with a design-matched null remains the default for ordering claims.')"""),
    (r"""p('We also compared CKI with Augur""",
     r"""p('We also compared CKI with Augur [37], which prioritizes cell types by condition predictability from single-cell expression, on the brain atlas (Supplementary Note 14). The rankings are moderately concordant (Augur separability versus class-mean \u03c9 Spearman \u03c1 = 0.442; versus k_f \u03c1 = 0.564) with overlapping extremes (astrocytes top by \u03c9, third by Augur), so CKI is not redundant with perturbation-prioritization tools, complementarity supported by the decomposition rather than ranking correlation alone; at n = 10 classes these correlations are descriptive only (multiclass and port-validation caveats in Supplementary Note 14).')"""),
    (r"""p('The pan-cancer reversal""",
     r"""p('The pan-cancer reversal\u2014tumor specimens less divergent than adjacent non-tumor tissue (mean NN/TT 1.10\u20132.46, cluster-bootstrap CIs excluding 1 in four of five cancers)\u2014is a robust tissue-level observation whose mechanistic reading remains cautious: at bulk resolution the apparent convergence could reflect cell-composition shifts, peritumoral inflammation, or RNA-quality differences rather than genuine transcriptional convergence, and the reversal is predominantly a k_n effect, so the data do not indicate smaller functional divergence of tumor cells. A marker-panel composition check quantifies the confound directly (Supplementary Note 8): tumor\u2013tumor pairs show larger composition differences, within which k_n correlates with the composition difference, yet covariate-adjusted regressions attenuate the tumor-pair coefficient by only \u22121.3% pooled (95% CI [\u22124.8%, +2.0%]). Marker panels being noisy proxies, these attenuation estimates are lower bounds: the pooled k_n excess is not fully explained by marker-measurable composition\u2014plausibly reflecting tumor-specific housekeeping dysregulation [38]\u2014but composition cannot be excluded either, and single-cell or deconvolution-based validation remains necessary. Tumor and adjacent non-tumor aliquots differ systematically in source site and batch, and adjacent non-tumor is not healthy tissue; separating tumor-specific housekeeping elevation from field effects requires an external healthy reference.')"""),
    (r"""p('The cross-organ and cross-brain-region analyses""",
     r"""p('The cross-organ and cross-brain-region analyses indicate CKI can serve as a general tool for measuring functional differentiation at multiple spatial scales, with one qualification: the brain regional gradient is a composite signal dominated by the k_n denominator (3.21-fold versus 2.03-fold from k_f), not a pure functional-divergence ranking. The candidate screen illustrates a second principle: 31 of 39 Strong candidates showed raw P < 0.05 but none survived correction (minimum q = 0.520; tier-dependence caveats in Supplementary Note 13)\u2014statistical claims at atlas scale require nulls respecting the experimental design, and the absence of FDR-significant signals is itself informative, delimiting what adult transcriptomes alone can support. Preliminary cross-species validation found no significant correlation of per-cell-type mean \u03c9 rankings (Spearman r = \u22120.17, P = 0.55; Supplementary Fig. 11), so cross-species transferability of \u03c9 remains unestablished [39].')"""),
    (r"""p('Although no individual candidate survives FDR correction""",
     r"""p('Although no individual candidate survives FDR correction, several signals are consistent with prior reports\u2014literature anchoring rather than independent validation. Maturation comparisons must use the k_f-only ordering, because the composite is k_n-dominated: under k_f alone the lineage ranks committed OPCs highest (k_f class mean 0.197, highest of ten classes though with the widest sampling uncertainty) above oligodendrocytes (0.054), with OPCs lowest (0.048)\u2014partially consistent with reports that early oligodendrocyte stages are regionally uniform whereas mature subsets become region-enriched [40,41]\u2014whereas the composite \u03c9 ordering gives the opposite picture; neither supports a monotone-maturation reading. The thalamo-temporal orientation of the mature-oligodendrocyte candidates concentrates on an axis rather than scattering across the 108 regions (descriptive comparison against two null references in Supplementary Note 13); correspondence with the developmental organization of forebrain oligodendrocytes [25] remains at the level of axis anatomy, pending lineage-tracing or spatial-transcriptomic follow-up.')"""),
    (r"""p('CKI and standard metrics answer different questions""",
     r"""p('CKI and standard metrics answer different questions, and choosing between them reduces to a few practical rules. Use CKI when the question is relative\u2014is the functional divergence between two populations larger than what their own housekeeping baseline varies by, within the same dataset and gene-selection scheme?\u2014offering a normalized, interpretable scale, higher discrimination than raw distances for strong perturbations, and a specificity-first screen: a significant \u03c9 rejects label exchangeability under a design-matched null, and functional signal on the anchor is invisible to \u03c9, as the IFN-\u03b2 demonstration makes explicit ([14]; Results). Before trusting fine-grained \u03c9 orderings, diagnose the denominator: if k_n lies in the extreme tail of its own null or correlates with technical covariates, report k_f with the design-matched null directly\u2014in the real data analyzed here, \u03c9 orderings were predominantly denominator-driven (Supplementary Note 9), so k_f plus a design-matched null is the honest default for ordering claims. Use standard metrics when absolute cross-dataset distances are required, for classification, for weak-to-moderate effects at atlas scale, or when the baseline itself is suspect\u2014then interpret k_n and k_f separately rather than trusting \u03c9 alone.')"""),
    (r"""p('For prospective applications we recommend""",
     r"""p('For prospective applications we recommend: (i) at least 100\u2013200 cells per group, below which pseudobulk noise inflates k_n and k_f unpredictably; (ii) the pre-specified HRT Atlas v1.0 housekeeping panel (cki/data/hrt_atlas.csv) rather than data-driven auto-detection; (iii) comparisons only within the same dataset and gene-selection scheme\u2014absolute \u03c9 does not transfer; (iv) calibration within the dataset of interest by split-half sampling, interpreting \u03c9 relative to that internal baseline rather than the mouse-derived 7.70; (v) a permutation null matching the experimental design (block-shuffle where libraries or donors define blocks; cki.blocknull.block_shuffle_test), expecting bounded sensitivity\u2014\u03c9 is a specificity-first screen whose value is rejecting neutral drift, not detecting weak functional shifts.')"""),
    (r"""p('Limitations. Several boundaries""",
     r"""p('Limitations. Several boundaries delimit where \u03c9 can fire and how it should be read. (i) Scope: CKI detects state changes within a given cell type, not cell-type identity; because the housekeeping anchor is cell-type-specific, the k_n baseline is directly comparable only within the same cell type, so limited cross-type discrimination of \u03c9 is expected by design and delineates, rather than limits, the index\u2019s scope; CKI currently operates at the pseudobulk level. (ii) Gene-set definition and calibration: the per-pair k_f scheme selects genes by the observed difference itself, so k_f magnitudes are inflated upper bounds (median 1.61-fold) and absolute tier thresholds are scheme-specific; housekeeping expression may be dysregulated in cancer [38]; and the empirical calibration factor (7.70, 95% CI [7.37, 8.02]) derives from mouse split-half controls, so absolute \u03c9 does not transfer across datasets or gene-selection schemes. Key parameters (top-200 DE genes, 2,000 HVGs, the +1 pseudo-count) are practical defaults, not optimized values. (iii) Data and design: the TCGA analysis is limited to bulk resolution, its per-cancer permutation test holds the identity panel fixed (anti-conservative), and with five cancer types the TCGA results are exploratory; the brain atlas uses post-mortem tissue, and donor-level PMI and RNA-integrity covariates were unavailable, so regionally differential RNA degradation could masquerade as regional structure in k_n. (iv) Anchor visibility: \u03c9 is structurally insensitive to perturbations that move the housekeeping anchor itself\u2014in simulation, once 500 genes shifted, the ratio collapsed (AUC 0.05\u20130.13)\u2014and donor-paired permutation power vanishes beyond roughly 500 cells per group, bounding the practical operating window at approximately 50\u2013200 cells; the scDist results were obtained with a Python approximation of the R package and should be re-verified against the original implementation. (v) Multiple testing and cluster-aware inference: the class-level upper-tail tests and the pair-level lower-tail screen are separate families reported without joint cross-family correction; the block-shuffle null assumes libraries are otherwise exchangeable, so systematic library-level confounding would distort the null in ways the permutation cannot capture\u2014bounded empirically by the pseudo-region negative control (Supplementary Note 12)\u2014and B = 1,000 bounds the resolvable P-value at 9.99 \u00d7 10\u207b\u2074, so the per-pair FDR outcome (minimum q = 0.520) is a statement about permutation resolution rather than evidence against any candidate. Full treatments of each limitation, with supporting sensitivity analyses, are given in Supplementary Notes 1\u201316.')"""),
    (r"""p('CKI adapts the baseline-normalization logic""",
     r"""p('CKI adapts the baseline-normalization logic of Ka/Ks to single-cell transcriptomics, decomposing population divergence into a housekeeping baseline rate (k_n) and an identity-gene functional rate (k_f). Across simulation, calibration, cross-organ, pan-cancer, and brain-regional analyses, \u03c9 rankings carried reproducible biological signal while absolute \u03c9 values remain scheme- and dataset-specific; statistical claims at atlas scale require nulls respecting the experimental design; and the absence of FDR-significant candidates is itself an informative bound on what adult transcriptomes alone can support. CKI is released as an open-source Python package with a fully reproducible pipeline, and we anticipate its use as an interpretable complement to standard distance metrics in comparative single-cell analyses.')"""),
]

used = set()
for idx, (pre, new) in enumerate(REPL):
    hits = [i for i, l in enumerate(src) if l.strip().startswith(pre) and i not in used]
    if len(hits) != 1:
        print(f'FAIL[{idx}] matched {len(hits)}: {pre[:70]}')
        sys.exit(1)
    i = hits[0]
    used.add(i)
    ow = len(src[i].split()); nw = len(new.split())
    src[i] = new
    print(f'L{i+1}: {ow} -> {nw}')

open(PATH, 'w', encoding='utf-8').write('\n'.join(src) + '\n')
print('WROTE OK')
